/**
 * Version checker — pure client-side polling, NO Service Worker, NO fetch
 * interception. Safe for the Supabase auth flow.
 *
 * See mem://constraints/auth-stability — this module must never:
 *  - register a Service Worker
 *  - intercept fetches
 *  - clear caches/localStorage automatically
 *  - reload the page automatically
 *
 * Behavior:
 *  - Reads /version.json (generated by plugins/versionPlugin at build) and
 *    compares its hash to import.meta.env.VITE_BUILD_HASH.
 *  - When a new hash is detected, shows a persistent sonner toast with an
 *    "Atualizar agora" button. Reload only happens on explicit click.
 *  - Skips the toast on routes where a flow in progress would be lost
 *    (assessment, payment, auth, etc). The detection is re-tried on every
 *    poll, so the toast appears as soon as the user navigates away.
 */
import { toast } from "sonner";

const POLL_INTERVAL_MS = 15 * 60 * 1000; // 15 minutes
const MIN_CHECK_GAP_MS = 30 * 1000; // throttle: don't refetch more than once per 30s
const TOAST_ID = "alivia-update-available";

// Routes where an in-flight flow must not be interrupted. The toast is
// suppressed entirely here — no banner, no nag — until the user navigates
// to a safe area (dashboard, landing pages, account, etc).
const UNSAFE_PATH_PREFIXES = [
  "/assessment", // basic + premium assessment in progress
  "/payment-success", // post-checkout reconciliation
  "/auth", // login / signup mid-request
  "/reset-password",
  "/aceitar-convite",
  "/complete-profile",
  "/upgrade-welcome",
  "/hep/", // patient exercise program token route
];

let started = false;
let currentHash: string | null = null;
let lastCheckAt = 0;
let pendingHash: string | null = null;

function getLocalHash(): string {
  // Injected by plugins/versionPlugin.ts at build time. In dev it is "__dev__".
  return (import.meta.env.VITE_BUILD_HASH as string | undefined) ?? "__dev__";
}

function isUnsafeRoute(): boolean {
  if (typeof window === "undefined") return true;
  const path = window.location.pathname;
  return UNSAFE_PATH_PREFIXES.some((prefix) =>
    prefix.endsWith("/") ? path.startsWith(prefix) : path === prefix || path.startsWith(prefix + "/"),
  );
}

function showUpdateToast(remoteHash: string) {
  if (isUnsafeRoute()) {
    // Remember the new hash and try again on the next visibility/focus event
    // or poll tick. Do not interrupt assessments/payments/auth.
    pendingHash = remoteHash;
    return;
  }

  pendingHash = null;

  toast("Nova versão disponível", {
    id: TOAST_ID,
    description: "Atualize para garantir os recursos mais recentes.",
    duration: Infinity,
    action: {
      label: "Atualizar",
      onClick: () => {
        try {
          const url = new URL(window.location.href);
          url.searchParams.set("v", remoteHash);
          // Replace (not reload) to bypass the HTML cache via the new query
          // string. We deliberately do NOT touch caches/localStorage — that
          // had broken auth in the past.
          window.location.replace(url.toString());
        } catch {
          window.location.reload();
        }
      },
    },
  });
}

async function checkOnce(force = false) {
  if (typeof window === "undefined") return;
  const local = getLocalHash();
  if (local === "__dev__") return; // never poll in dev

  const now = Date.now();
  if (!force && now - lastCheckAt < MIN_CHECK_GAP_MS) return;
  lastCheckAt = now;

  try {
    const res = await fetch(`/version.json?t=${now}`, {
      cache: "no-store",
      credentials: "omit",
    });
    if (!res.ok) return;
    const data = (await res.json()) as { hash?: string };
    const remote = data?.hash;
    if (!remote || typeof remote !== "string") return;

    currentHash = remote;
    if (remote !== local) {
      showUpdateToast(remote);
    }
  } catch {
    /* network hiccup — try again next tick */
  }
}

function maybeShowPending() {
  // Called on visibility/focus/route transitions to surface a previously
  // suppressed update once the user is on a safe route again.
  if (pendingHash && !isUnsafeRoute()) {
    showUpdateToast(pendingHash);
  }
}

export function startVersionChecker() {
  if (started) return;
  started = true;
  if (typeof window === "undefined") return;

  // Initial check shortly after mount (don't block first paint)
  setTimeout(() => void checkOnce(true), 2000);

  // Reopening the PWA shortcut on mobile fires both visibilitychange and
  // focus — those are the highest-signal moments for a refresh.
  window.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
      maybeShowPending();
      void checkOnce();
    }
  });
  window.addEventListener("focus", () => {
    maybeShowPending();
    void checkOnce();
  });

  // Periodic poll while the tab is open
  setInterval(() => {
    if (document.visibilityState === "visible") void checkOnce();
  }, POLL_INTERVAL_MS);

  // SPA navigations don't fire focus/visibility — re-evaluate the pending
  // toast whenever history changes, so leaving an unsafe route surfaces it.
  const surface = () => maybeShowPending();
  window.addEventListener("popstate", surface);
  const origPush = history.pushState;
  const origReplace = history.replaceState;
  history.pushState = function (...args) {
    const r = origPush.apply(this, args as never);
    queueMicrotask(surface);
    return r;
  };
  history.replaceState = function (...args) {
    const r = origReplace.apply(this, args as never);
    queueMicrotask(surface);
    return r;
  };
}

export function _getCurrentRemoteHash() {
  return currentHash;
}
